-- 100: Great Lakes / Midwest fishing rules (US plan step 4): Ohio, Michigan, Indiana, Illinois, Wisconsin, Minnesota, Iowa, Missouri
-- Checked 2026-10-21 on each state's own pages (links in source_url): Ohio Administrative Code rule 1501:31-13-08 (effective July 6, 2026);
-- Michigan 2026 Fishing Regulations digest (rules apply from April 1, 2026); Indiana statewide size and bag table on eRegulations (2026-27, page updated Oct 20, 2026);
-- Illinois Administrative Code 17 Ill. Adm. Code 810.35 (ilga.gov); Wisconsin Guide to Hook and Line Fishing Regulations 2026-2027 (effective Apr 1, 2026 – Mar 31, 2027);
-- Minnesota Rule 6262.0200 (revisor.mn.gov, published April 8, 2026); Iowa Fishing Seasons and Limits on eRegulations (updated Sept 23, 2026); Missouri MDC Fishing Limits page (2026 dates).
-- A state rule is a normal fish_rules row whose `regions` holds the 2-letter state code. Needs setup/94 first (its check already allows these codes).
-- Where a rule changes by season, zone or water the app can only show one number, so the STRICTER one is the size / closed dates and the note has the rest.
-- Closed dates are written as the longest closed stretch that is closed in EVERY year (dates that move, like "Saturday before Memorial Day", use the latest possible day).
-- NOT added: Ohio bluegill / sunfish and bass minimum lengths (the rule page sets none; lake-by-lake lengths are in the Ohio guide), Michigan and Wisconsin and Indiana and
-- Illinois trout and salmon (trout have their own separate guides / stream lists that were not read), Michigan Great Lakes salmon and trout, Illinois yellow perch,
-- Missouri northern pike (its row on the page is dated 2025), Wisconsin whitefish and cisco. The app says "We don't have a <State> rule for this fish yet" for those.
-- Insert only; no delete / drop.

insert into fish_rules (species, match, regions, min_in, max_in, measure, one_over, bag, release_only, closed, open_only, note, source_url, verified_on, active) values
-- ---------------- Ohio (Ohio Administrative Code 1501:31-13-08, effective July 6, 2026) ----------------
 ('Black bass (largemouth, smallmouth, spotted)', array['largemouth','smallmouth','black bass','spotted bass'], array['OH'], null, null, 'total', false, '5 per day (all three together)', false, null, null,
  'This rule sets no statewide minimum length, but many lakes post their own (some 14-20″ slots, 3-4 per day). Lake Erie waters: 1 per day from May 1 to the fourth Saturday in June. Check the lake and the Ohio guide.',
  'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Walleye, sauger and saugeye', array['walleye','saugeye','sauger'], array['OH'], null, null, 'total', false, '6 per day (all three together)', false, null, null,
  'Lake Erie and the Ohio River have their own limits (Lake Erie walleye limits are set each spring from the harvest quota). No statewide minimum length in this rule.',
  'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Muskellunge', array['muskellunge','muskie','musky'], array['OH'], null, null, 'total', false, '1 per day (muskellunge and tiger muskellunge together)', false, null, null,
  'No minimum length in this rule; some lakes post one.', 'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Trout and salmon', array['rainbow trout','brown trout','brook trout','steelhead','chinook','coho','king salmon'], array['OH'], null, null, 'total', false, '2 per day (5 on most waters, all trout and salmon together)', false, null, null,
  '5 per day on most waters; only 2 per day in the Mad River, Clear Fork of the Mohican, a stretch of Clear Creek, and in Lake Erie and its streams Sep 1 – May 15 (the stricter 2 is shown). Keeping brook trout is not allowed in the Ashtabula, Chagrin, Conneaut and Grand rivers.',
  'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Yellow perch', array['yellow perch'], array['OH'], null, null, 'total', false, '30 per day', false, null, null,
  'Lake Erie, the Ohio River and Pymatuning Lake have their own limits (Lake Erie perch limits depend on the zone and are set each year).',
  'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('White, striped and hybrid striped bass', array['white bass','striped bass','hybrid striped bass','hybrid bass','wiper'], array['OH'], null, null, 'total', false, '30 per day (all together), no more than 4 over 15″', false, null, null,
  'Lake Erie and Pymatuning Lake have their own rules.', 'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Catfish', array['channel catfish','flathead catfish','blue catfish','catfish'], array['OH'], null, null, 'total', false, 'No limit under the sizes below; 1 per day channel catfish 28″ or longer, 1 flathead and 1 blue catfish 35″ or longer', false, null, null,
  'Pymatuning Lake has its own rule.', 'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
 ('Crappie', array['crappie','speckled perch'], array['OH'], null, null, 'total', false, 'No daily limit on most waters; 30 per day in 27 named lakes (Alum Creek, Buckeye, Caesar Creek, Hoover, Mosquito, Salt Fork and others), 10 per day in St. Joseph River, Oxbow Lake and Killdeer Plains areas', false, null, null,
  'No statewide minimum length in this rule.', 'https://codes.ohio.gov/ohio-administrative-code/rule-1501:31-13-08', '2026-10-21', true),
-- ---------------- Michigan (2026 Michigan Fishing Regulations, general table, rules apply from April 1, 2026) ----------------
 ('Largemouth and smallmouth bass', array['largemouth','smallmouth','black bass'], array['MI'], 14, null, 'total', false, '5 per day (both together)', false, '[["01-01","06-20"]]'::jsonb, null,
  'You may keep bass from the Saturday before Memorial Day to Dec 31 on most waters (the 3rd Saturday in June on Lake St. Clair and the St. Clair and Detroit rivers, which is the stricter date shown). Catch and release is open all year on all waters.',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Walleye', array['walleye','saugeye','sauger'], array['MI'], 15, null, 'total', false, '5 per day', false, '[["03-16","05-14"]]'::jsonb, null,
  'Open May 15 – Mar 15 in the Upper Peninsula (the stricter dates shown); Lower Peninsula inland waters open the last Saturday in April; Lower Peninsula Great Lakes, Lake St. Clair, St. Clair and Detroit rivers open all year. Saginaw Bay: 8 per day and 13″ minimum. Lake Erie, Detroit River and Lake St. Clair: limit changes each year (6 through Apr 30, 2026). Some lakes have slot limits.',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Northern pike', array['northern pike','pike'], array['MI'], 24, null, 'total', false, '2 per day', false, '[["03-16","05-14"]]'::jsonb, null,
  'Open May 15 – Mar 15 in the Upper Peninsula (the stricter dates shown); Lower Peninsula inland waters open the last Saturday in April; the Lower Peninsula Great Lakes, Lake St. Clair and the St. Clair and Detroit rivers are open all year. Some lakes have no size limit and up to 5 pike (one 24″ or longer).',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Muskellunge (and tiger muskellunge)', array['muskellunge','muskie','musky'], array['MI'], 42, null, 'total', false, '1 per angler per license year (April 1 – March 31)', false, '[["01-01","06-06"]]'::jsonb, null,
  'You must register a kept muskellunge within 24 hours. Open the first Saturday in June to Mar 15 (to Dec 31 on Lake St. Clair, St. Clair and Detroit rivers, the stricter end shown). Some waters have 46″ or 50″ minimums. Catch and release is open all year.',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Channel catfish', array['channel catfish','catfish'], array['MI'], 12, null, 'total', false, '10 per day', false, null, null,
  'Open all year. Flathead catfish: 15″ minimum, 5 per day.',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Flathead catfish', array['flathead catfish','flathead'], array['MI'], 15, null, 'total', false, '5 per day', false, null, null,
  'Open all year.', 'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Yellow perch', array['yellow perch'], array['MI'], null, null, 'total', false, '25 per day', false, null, null,
  'Open all year, no size limit. Some lakes and Lake Erie have a different limit (for example no more than 5 perch 12″ or longer).',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('Sunfishes (bluegill, crappie, rock bass and others)', array['bluegill','pumpkinseed','sunfish','panfish','rock bass','crappie','speckled perch'], array['MI'], null, null, 'total', false, '25 per day (all the sunfishes together, black and white crappies included)', false, null, null,
  'Open all year, no size limit. Michigan counts black and white crappie, bluegill, green and hybrid sunfish, longear, pumpkinseed, redear, rock bass and warmouth in this one limit.',
  'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-21', true),
 ('White bass', array['white bass','wiper','hybrid bass'], array['MI'], null, null, 'total', false, '10 per day on inland waters (25 on the Great Lakes and connecting waters)', false, null, null,
