 ('Northern pike', array['northern pike','pike'], array['WI'], 26, null, 'total', false, '2 per day south of Highway 10 (the stricter number shown); 5 per day, any length, north of Highway 10', false, '[["03-08","05-01"]]'::jsonb, null,
