 ('Smallmouth bass', array['smallmouth','smallie'], array['MN'], null, null, 'total', false, '6 per day and in possession (largemouth and smallmouth together)', false, '[["09-09","05-28"]]'::jsonb, null,
  'Harvest from the Saturday of Memorial Day weekend to the second Sunday in September (the stricter dates shown); in the northeast zone the opener is two weeks earlier and harvest runs to the last Sunday in February. At other times catch and release only.',
  'https://www.revisor.mn.gov/rules/6262.0200/', '2026-10-21', true),
 ('Walleye and sauger', array['walleye','saugeye','sauger'], array['MN'], null, null, 'total', false, '6 per day (together)', false, '[["02-23","05-14"]]'::jsonb, null,
  'Open from the Saturday two weeks before Memorial Day weekend to the last Sunday in February (the latest opener and earliest close shown). Many lakes and rivers have special limits (Mille Lacs: 3, 17″ minimum in 2026).',
  'https://www.revisor.mn.gov/rules/6262.0200/', '2026-10-21', true),
 ('Northern pike', array['northern pike','pike'], array['MN'], 24, null, 'total', false, '2 per day (southern zone and northeast zone); 10 per day in the north-central zone', false, '[["02-23","05-14"]]'::jsonb, null,
  'Southern zone: 24″ minimum, 2 fish. Northeast zone: 2 fish, only 1 over 40″, and pike 30 to 40″ must be released. North-central zone: 10 fish, only 2 over 26″, and pike 22 to 26″ must be released. The southern 24″ and the earlier close are shown. Same season as walleye.',
  'https://www.revisor.mn.gov/rules/6262.0200/', '2026-10-21', true),
 ('Muskellunge', array['muskellunge','muskie','musky'], array['MN'], 54, null, 'total', false, '1', false, '[["12-01","06-06"]]'::jsonb, null,
